import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display an error for invalid card number', async ({ page }) => {
    await page.fill('input[name="cardNumber"]', '1234 5678 9012 3456'); // Example of an invalid card number
    await page.click('button[type="submit"]');

    const errorMessage = await page.getByText('Invalid card number');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display an error for valid card number', async ({ page }) => {
    await page.fill('input[name="cardNumber"]', '4111 1111 1111 1111'); // Example of a valid card number
    await page.click('button[type="submit"]');

    const errorMessage = await page.getByText('Invalid card number');
    await expect(errorMessage).not.toBeVisible();
  });
});
